The scattered field $u^{sc}$ corresponding to the first equation of \eqref{Traction free Navier equation} is said to be a Kupradze radiating solution if its compressional part $u_p^{sc}$ and shear part $u_s^{sc}$ fulfill the Sommerfeld radiation condition for the vector Helmholtz equation, that is, 

\begin{equation}
\label{eq:15}
\lim_{r \to \infty} \sqrt{r}\left( \frac{\partial u_{p}^{\mathrm{sc}}}{\partial r} - i k_{p} u_{p}^{\mathrm{sc}} \right) = 0, \  \  
\lim_{r \to \infty} \sqrt{r}\left( \frac{\partial u_{s}^{\mathrm{sc}}}{\partial r} - i k_{s} u_{s}^{\mathrm{sc}} \right) = 0, \  \   r = |x|,
\end{equation}
and the above limits hold uniformly as $\widehat{x}=x/|x|$ ranges over $\mathbb{S}^{1} := \{ x \in \mathbb{R}^2 : |x|=1 \}$.

\label{thm:main_result}
Let $D_1 , D_2 \subset \mathbb{R}^2 $ be two bounded polygonal obstacles such that $D_1^c$ and $D_2^c$ are connected. For $j=1, 2$, let $u_j^\infty$ denote the elastic far-field pattern corresponding to the scattering problem \eqref{eq:7}-\eqref{eq:9}, generated by an incident plane wave \eqref{eq:plane} with a fixed incident direction ${d} \in \mathbb{S}^1$ and a fixed frequency $\omega > 0$. If 
\begin{align*}
u_1^\infty(\widehat{x}) = u_2^\infty(\widehat{x}) \  \text{for all } \widehat{x} \in \mathbb{S}^1,
\end{align*}
then 
\begin{align*}    
D_1 = D_2.
\end{align*}

\label{thm:reflection}
Suppose that $u(x_1,x_2)=(u_1(x_1,x_2),u_2(x_1,x_2))$ is a solution to  the following Lam\'e system with the traction-free boundary  condition 
\begin{equation}
\label{Reflection: Lame system traction free condition}
\begin{cases}
\mathcal{L}u=\mu \Delta u + (\lambda + \mu)\nabla(\nabla \cdot u)  = 0\quad \text{in }\; \Omega^+, \\
 T_{\nu}(u)=2\mu\, \partial_\nu u + \lambda\, (\nabla \cdot u)\nu 
+ \mu\, (\nabla \times u)\, \nu^{\perp} = 0\quad \text{on }\; \gamma.
\end{cases}
\end{equation}
Then $u$ can be analytically extended from $\Omega^+$ to  $\Omega$ as a solution to \eqref{Reflection: Lame system traction free condition}. Moreover, the extended field $\widetilde u(x_1,x_2)=(\widetilde u_1(x_1,x_2),\widetilde u_2(x_1,x_2))$ on $\Omega$  is explicitly given by 
 \begin{equation}
 \label{eqn:Extension}
    \widetilde u(x_1,x_2) :=
        \begin{cases}
          u(x_1,x_2) &\text{  if  } (x_1, x_2) \in \Omega^+ \cup \gamma,\\
          \mathcal{B}u(R_\Lambda (x_1,x_2)) &\text{ if  } (x_1,x_2) \in \Omega^-,
        \end{cases}
    \end{equation}
    where $\mathcal{B}$ is the linear operator mapping the space of analytic functions in $\Omega^+$ into itself and given by $\mathcal{B}u=((\mathcal{B}u)_1,(\mathcal{B}u)_2)$ where, for $(x_1,x_2)\in \Omega^+$,
    \begin{align}\label{eq:2.5}
 (\mathcal{B}u)_1(x_1,x_2)
&=
\frac{\lambda+3\mu}{\lambda+\mu}\,
u_1(x_1,x_2)
-\frac{2\mu}{\lambda+\mu}\,
u_1(0,x_2)
+\frac{\mu(\lambda+2\mu)}{(\lambda+\mu)^2}
\int_0^{x_1} f(s,x_2)\,ds \notag
\\
&\quad
-2x_1\,\partial_1u_1(x_1,x_2)
-\frac{2\mu}{\lambda+\mu}\,
x_1f(x_1,x_2)
+x_1^2\,\partial_1f(x_1,x_2),
\end{align}
and 
\begin{align}\label{eq:2.6}
(\mathcal{B}u)_2(x_1,x_2)
&=
u_2(x_1,x_2)
+\frac{2\mu}{\lambda+\mu}
\int_0^{x_1}\partial_2u_1(s,x_2)\,ds
-\frac{2\mu}{\lambda+\mu}\,
x_1\partial_2u_1(0,x_2) \notag \\ & \ \
+2x_1\partial_2u_1(x_1,x_2)
+\frac{\mu(\lambda+2\mu)}{(\lambda+\mu)^2}
\int_0^{x_1}(x_1-t)\,
\partial_2f(t,x_2)\,dt
\notag \\
&\quad
-x_1^2\partial_2f(x_1,x_2).
\end{align}
Here the function $f$ is given by \eqref{ex-f}.

\label{thm:reflection nav}
Let $\gamma \subset \Lambda$ and $\Omega =\Omega^+ \cup \gamma \cup \Omega^-$ be a symmetric domain as defined before. Suppose that $u(x_1,x_2)=(u_1(x_1,x_2),u_2(x_1,x_2))$ is a solution to the following Navier equation satisfying the traction-free boundary condition 
\begin{equation}
\label{eq:3.1}
\begin{cases}
\mathcal{N}_\omega u := \mathcal{L}u+\omega^2 u=0\ \text{in }\Omega^+ ,\\
 T_{\nu}(u) := 2\mu\, \partial_\nu u 
+ \lambda\,(\nabla \cdot u)\nu
+ \mu\,(\nabla \times u)\, \nu^{\perp} = 0\ \text{on } \gamma.
\end{cases}
\end{equation}
Then $u$ can be analytically extended  to $\Omega^-$ as a solution to \eqref{eq:3.1}. Moreover, there exists an extension operator $\mathcal{\widetilde B}$  such that
$$
u(-x_1, x_2):= ( \mathcal{\widetilde B} u)(x_1, x_2), \  (x_1,x_2) \in \Omega^+, 
$$
where we refer to \eqref{eq:3.8} for a  definition of the operator $\mathcal{\widetilde B}$.

Let $u$ be a solution to \eqref{eq:3.1}. Define a new function
\begin{equation}
\label{eq:v_def}
\widehat{u}(x)
:=
u(x)
-
\omega^{2}
\int_{\Omega^{+}} G(x,y)\,u(y)\,dy,
\  \   x \in \Omega^{+},
\end{equation}
where $G(x,y)$ is the Green's tensor given by \eqref{eq:green}.
Now it is easy to check that $\widehat{u}$ satisfies the Lam\'e system with traction-free boundary condition, that is,
\begin{equation}
\label{eq:v_bvp}
\begin{cases}
\mathcal{L}\widehat{u}:=\mu \Delta \widehat{u} + (\lambda+\mu)\nabla(\nabla\cdot \widehat{u}) = 0
& \text{in }\, \Omega^{+}, \\
T_{\nu}(\widehat{u}):=2\mu\,\partial_\nu \widehat{u} + \lambda (\nabla\cdot \widehat{u})\,\nu
+ \mu (\nabla \times \widehat{u})\,\nu^{\perp} = 0
&  \text{on}\, \gamma.
\end{cases}
\end{equation}
Applying Theorem ~\ref{thm:reflection} and the definition of the operator $\mathcal{B}$ in \eqref{eqn:Extension}, we conclude that $\widehat{u}$ can be extended analytically to $\Omega^-$ as a solution to the Lam\'e system. After denoting the extended function again by $\widehat{u}$,
we obtain
\begin{equation}
\label{eq:v_extension}
\widehat{u}(-x_1,x_2) = (\mathcal{B}\widehat{u})(x_1,x_2),
\  x \in \Omega.
\end{equation}
Now substitute \eqref{eq:v_def} in  \eqref{eq:v_extension},
to deduce that  
\begin{align}
\label{eq:3.8}
u(-x_1,x_2)
&=
(\mathcal Bu)(x)
-
\omega^{2}
\int_{\Omega^{+}} \mathcal{B}_x G(x,y)\,u(y)\,dy
\nonumber \\
&\ 
+
\omega^{2}
\int_{\Omega^{+}} G((-x_1,x_2),y)\,u(y)\,dy
=: (\widetilde{\mathcal{B}}u)(x),
\  \   x \in \Omega^{+}.
\end{align}
The representation \eqref{eq:3.8} defines an extension of $u$ from $\Omega^+$ to $\Omega^-$. By construction, this extension satisfies the Navier equation in $\Omega^-$, and hence in the full domain $\Omega$. This finishes the proof of Theorem~\ref{thm:reflection nav}.

\label{lem:2}
Let \(D \subset \mathbb{R}^2\) be an unbounded domain that contains the sector \(A_0\). Assume that \(u\) satisfies the Navier equation \eqref{Equation for Incident field} in $D$, with the traction-free boundary condition \eqref{eq:8} on $\Lambda_0 \cup \Lambda_1$, that is,
\begin{equation}
\label{eq:aa}
\begin{cases}
\mathcal{N}_\omega(u) = 0\ \text{in } D, \\
T_\nu(u) = 0\ \text{on } \Lambda_0 \cup \Lambda_1.
\end{cases}
\end{equation}
Then $u$ admits an analytic extension to the whole space $\mathbb{R}^2$.

\begin{proof}
Let $u$ satisfy the boundary value problem \eqref{eq:aa}. Since $A_0 \subset D$, we may consider the restriction of $u$ to $A_0$.
By Theorem~\ref{thm:reflection nav}, $u$ admits an analytic extension across the boundary $\Lambda_1$ into the sector $A_1$, given by
\begin{equation*}
u(x) = (\widetilde{\mathcal{B}}_1 u)\big(R_{\Lambda_1} x\big), \  x \in A_1,
\end{equation*}
where $\widetilde{\mathcal{B}}_1$ is the extension operator associated with the traction-free boundary condition $T_\nu(u)=0$ on $\Lambda_1$. 
Introduce the function
\begin{equation*}
v(x):=R_{\Lambda_1}u(R_{\Lambda_1}x) =R_{\Lambda_1} (\widetilde{\mathcal{B}}_1 u)(x), \  x \in A_0 \cup \Lambda_1 \cup A_1.
\end{equation*}

Since the reflection $R_{\Lambda_1}$ maps $\Lambda_0$ onto $\Lambda_2$, and since both the Navier equation and the traction operator are invariant under reflection, it follows from Proposition \ref{pro} that the field $v$ obtained above satisfies the traction-free boundary condition on $\Lambda_2$.

\noindent Applying Theorem~\ref{thm:reflection nav} again, now across the side $\Lambda_2$, we obtain an analytic extension of $u$ from $A_1$ into $A_2$, and this extension satisfies the traction-free boundary condition on $\Lambda_3$. Repeating this argument inductively, we obtain an analytic extension of $u$ from $A_0$ into the successive sectors $A_j$ for $j\ge1$, with $T_\nu(u)=0$ on each of the rays $\Lambda_j$. 


Now, since $\theta_0 \in (0,\tfrac{\pi}{2}]$, there exists an integer $k \geq 2$ such that
$
k\theta_0 \geq \pi.
$
By iterating the above reflection-extension procedure $k-1$ times, $u$ can be analytically extended to the right half-plane $\{x_1 \geq 0\}$.
Moreover, the extended function satisfies the traction-free boundary condition
$$
T_\nu(u) = 0 \  \text{on } \{x_1 = 0\}.
$$
Applying Theorem \ref{thm:reflection nav} again across the line $\{x_1=0\}$, we further extend $u$ from $\mathbb{R}^2_+$ to the entire space $\mathbb{R}^2$. This completes the proof of the lemma.
\end{proof}

\label{lem:3}
Assume that \(u\) satisfies the Navier equation \eqref{Equation for Incident field} in $D \cup \gamma \cup G$, with the traction-free boundary condition \eqref{eq:8} on $\partial D$, that is,
\begin{equation}
\label{eq:abc}
\begin{cases}
\mathcal{N}_\omega(u) = 0 \  \text{in } D \cup \gamma \cup G, \\
T_\nu(u) = 0 \  \text{on } \partial D.
\end{cases}
\end{equation}
Then the following statement holds
\begin{enumerate}
    \item[(i)] The reflected field $w :=R_{\Lambda}\circ\mathcal{\widetilde B}u$ admits an analytic extension to $G \cup R_\Lambda(D)$ as a solution to the Navier equation with traction-free boundary condition  \eqref{eq:8}  on $\partial R_{\Lambda}(D)$. 
    \item[(ii)] Suppose that there exists a half-plane contained in $G$ whose boundary line extends one side of $\partial R_{\Lambda}(D)$. Then both $w$ and $u$ admit analytic continuation to the entire plane $\mathbb{R}^2$.
\end{enumerate}
